import { register } from '@shopify/theme-sections';
import { fetchProductData, getElement } from '../utils/functional';
import { ProductDetail } from './product/detail';
import { selectors } from './product/utilities';
register('product', {
  async onLoad() {
    const form = getElement(selectors.form);
    if (!form) throw new Error("An element with \"".concat(selectors.form, "\" should exist on the page"));
    this.data = await fetchProductData(this.container.dataset.productHandle);
    this.detail = new ProductDetail(this, form);
  }

});