import { getElement, getElements } from '../../utils/functional';
import { Listeners } from '../../utils/listeners';
import { selectors } from './utilities';
export class SizeSelector {
  constructor(detail) {
    this.listeners = new Listeners();
    this.detail = detail;
    this.setupListeners();
  }

  setupListeners() {
    this.onChoiceClick = this.onChoiceClick.bind(this);
    this.listeners.add(this.choicesContainer, 'click', this.onChoiceClick);
  }

  onChoiceClick(e) {
    if (!e.target.closest(selectors.choice)) return;
    const currentChoice = e.target.closest(selectors.choice);
    this.choices.map(choice => choice.setAttribute('aria-current', choice.dataset.value === currentChoice.dataset.value));
    this.select.value = currentChoice.dataset.value;
    this.select.dispatchEvent(new Event('change'));
    this.detail.sizeChosen = true;
  }

  get container() {
    return getElement(selectors.sizeOption);
  }

  get choicesContainer() {
    return getElement(selectors.choices, {
      context: this.container
    });
  }

  get choices() {
    return getElements(selectors.choice);
  }

  get select() {
    return getElement(selectors.select, {
      context: this.container
    });
  }

}