import { getUrlWithVariant } from '@shopify/theme-product-form';
import { formatMoney, getElement, getElements } from '../../utils/functional';
import { selectors, updateUrl } from './utilities';
export class Variant {
  constructor(data, detail) {
    this.data = data;
    this.detail = detail;
  }

  render() {
    this.setUrl();
    this.setPrice();
    this.setAvailability();
  }

  setAvailability() {
    getElements(selectors.submit).forEach(submit => {
      submit.disabled = !this.available;
      /* Add back in stock trigger to add to cart button */

      if (this.available) {
        submit.removeAttribute('data-module-drawers-trigger');
      } else {
        submit.setAttribute('data-module-drawers-trigger', 'bis');
      }
    });
    getElements(selectors.submitText).forEach(submitText => {
      submitText.innerHTML = this.available ? submitText.dataset.translationAddToCart : submitText.dataset.translationSoldOut;
    });
  }

  setPrice() {
    const priceElements = getElements(selectors.price);
    priceElements.forEach(el => el.innerHTML = formatMoney(this.data.price, '£{{amount_no_decimals}}'));
    const inactiveButtonPrice = getElement("".concat(selectors.priceButton, "[aria-current='false']"));
    const activeButtonPrice = getElement("".concat(selectors.priceButton, "[aria-current='true']"));
    inactiveButtonPrice.innerHTML = formatMoney(this.data.price, '£{{amount_no_decimals}}');
    if (this.detail.sizeChosen !== 'true') return;
    const submit = getElement(selectors.submit);
    submit.dataset.changing = 'true';

    const onTransitionEnd = e => {
      if (e.target !== inactiveButtonPrice) return;
      submit.dataset.changing = 'out';
      activeButtonPrice.innerHTML = formatMoney(this.data.price, '£{{amount_no_decimals}}');
      window.setTimeout(() => {
        activeButtonPrice.setAttribute('aria-current', 'false');
        inactiveButtonPrice.setAttribute('aria-current', 'true');
        window.setTimeout(() => {
          submit.dataset.changing = 'false';
        }, 25);
        submit.removeEventListener('transitionend', onTransitionEnd);
      }, 25);
    };

    submit.addEventListener('transitionend', onTransitionEnd);
  }

  setUrl() {
    updateUrl(getUrlWithVariant(window.location.href, this.id));
  }

  get available() {
    return this.data.available;
  }

  get id() {
    return this.data.id;
  }

}