import { ProductForm } from '@shopify/theme-product-form';
import { SizeSelector } from './size-selector';
import { updateUrl } from './utilities';
import { Variant } from './variant';
export class ProductDetail {
  constructor(section, form) {
    this.section = section;
    this.variants = this.data.variants.map(v => new Variant(v, this));
    this.onOptionChange = this.onOptionChange.bind(this);
    this.productForm = this.setupProductForm(form);

    if (this.hasSizeOption) {
      this.sizeSelector = new SizeSelector(this);
    }
  }

  setupProductForm(form) {
    const productForm = new ProductForm(form, this.data, {
      onOptionChange: this.onOptionChange,
      onQuantityChange: () => {}
    });
    return this.patchProductForm(productForm);
  }

  patchProductForm(productForm) {
    if (productForm.options().length === 0) {
      const submitListener = productForm._listeners.entries.find(listener => listener.event === 'submit');

      submitListener.element.removeEventListener(submitListener.event, submitListener.fn);
      productForm._listeners.entries = productForm._listeners.entries.filter(entry => entry.event !== 'submit');
    }

    return productForm;
  }

  onOptionChange(e) {
    if (e.dataset.variant === null) {
      this.resetPage();
      return;
    }

    this.setWishlistVariantId(e.dataset.variant.id);
    this.setBackInStockVariantId(e.dataset.variant.id);
    this.findVariant(e.dataset.variant).render();
  }

  resetPage() {
    this.defaultVariant.setPrice();
    updateUrl(window.location.pathname);
    this.defaultVariant.setAvailability();
  }

  findVariant(variant) {
    return this.variants.find(v => v.id === variant.id);
  }

  setWishlistVariantId(variantId) {
    const wishlistAddTrigger = document.querySelector('.js-Wishlist_Button-add');
    const wishlistRemoveTrigger = document.querySelector('.js-Wishlist_Button-remove');

    if (wishlistRemoveTrigger) {
      wishlistRemoveTrigger.dataset.variant = variantId;
    }

    if (wishlistAddTrigger) {
      wishlistAddTrigger.dataset.variant = variantId;
      /* Toggle the remove trigger - 'iwishAdded' class required by iwish app */

      const productId = wishlistAddTrigger.dataset.product ? parseInt(wishlistAddTrigger.dataset.product) : null;

      if (window.iWishlistmain && productId && window.iWishlistmain[productId]) {
        if (window.iWishlistmain[productId].includes("".concat(variantId))) {
          wishlistAddTrigger.classList.add('iwishAdded');
        } else {
          wishlistAddTrigger.classList.remove('iwishAdded');
        }
      }
    }
  }

  setBackInStockVariantId(variantId) {
    const backInStockTrigger = document.querySelector('[data-el="back-in-stock.trigger"]');

    if (backInStockTrigger) {
      backInStockTrigger.dataset.variantId = variantId;
    }
  }

  get defaultVariant() {
    return this.variants[0];
  }

  get hasSizeOption() {
    return this.section.container.dataset.hasSizeOption === 'true';
  }

  get sizeChosen() {
    return this.section.container.dataset.sizeChosen;
  }

  set sizeChosen(val) {
    this.section.container.dataset.sizeChosen = val;
  }

  get data() {
    return this.section.data;
  }

}