import { getElements } from '../../utils/functional';
export const selectors = {
  choices: '[data-product-detail-choices]',
  choice: '[data-product-detail-choice]',
  form: '[data-product-detail-form]',
  price: '[data-product-detail-price]',
  priceButton: '[data-product-detail-button-price]',
  priceCompare: '[data-product-detail-price-compare]',
  select: '[data-product-detail-select]',
  sizeOption: '[data-product-detail-size-option]',
  submit: '[data-product-detail-submit]',
  submitText: '[data-product-detail-submit-text]'
};
export function updateUrl(url) {
  window.history.replaceState({
    path: url
  }, '', url);
}
export function hideElements(elements) {
  elements.forEach(el => el.hidden = true);
}
export function unhideElements(elements) {
  elements.forEach(el => el.hidden = false);
}
